	"Error: Timeout %1": "\u06a9\u0646\u06a9\u0634\u0646 \u062f\u0627 \u0648\u0642\u062a \u062d\u062f \u062a\u0648\u06ba \u0648\u062f\u06be\u06cc\u0627: %1",
	"Error: read ECONNRESET": "\u067e\u06cc\u0626\u0631 \u06a9\u0646\u06a9\u0634\u0646 \u062e\u062a\u0645 \u06a9\u06cc\u062a\u0627",
