	"\u81ea\u7db2\u8def\u53d6\u5f97 URL\uff1a%1": "\u06cc\u0648 \u0622\u0631 \u0627\u06cc\u0644 \u0622\u0646\u0688\u0627 \u067e\u0626\u06d2: %1",
	"Got error when retrieving [%1]: %2": "[%1] \u0622\u0646\u0688\u06d2 \u0648\u06cc\u0644\u06d2 \u062e\u0631\u0627\u0628\u06cc \u062a\u06be\u0626\u06cc: %2",
	"\u81ea\u7db2\u8def\u53d6\u5f97 URL\uff1a%1\uff0c%2{{PLURAL:%2|\u4f4d\u5143\u7d44}}\u3002": "\u0646\u06cc\u0679 \u0648\u0631\u06a9 \u062a\u0648\u06ba \u06cc\u0648 \u0622\u0631 \u0627\u06cc\u0644 \u0645\u0644\u06cc\u0627: %1\u060c %2 {{PLURAL:%2|byte|bytes}}\u06d4",
	"Invalid cookie?": "\u063a\u06cc\u0631 \u0645\u0639\u062a\u0628\u0631 \u06a9\u0648\u06a9\u06cc\u061f",
	"cookie \u540d\u7a31\u91cd\u8907\uff01\u4ee5\u5f8c\u4f86/\u65b0\u51fa\u73fe\u8005\u70ba\u6e96\u3002": "\u062f\u0648\u06c1\u0631\u0627 \u06a9\u0648\u06a9\u06cc \u0646\u0627\u06ba! \u067e\u0648\u0648\u06cc\u06ba/\u0646\u0648\u0627\u06ba \u0622\u0644\u0627 \u0686\u0644\u0633\u06cc\u06d4",
	"Waiting %1/%2 {{PLURAL:%1|connection|connections}}: %3": "\u0627\u0646\u062a\u0638\u0627\u0631 %1/%2 {{PLURAL:%1|\u06a9\u0646\u06a9\u0634\u0646|\u06a9\u0646\u06a9\u0634\u0646\u0632}}: %3",
	"Using HTTPS proxy to get URL: %1": "\u06cc\u0648 \u0622\u0631 \u0627\u06cc\u0644 \u0622\u0646\u0768 \u06a9\u06cc\u062a\u06d2 HTTPS \u067e\u0631\u0648\u06a9\u0633\u06cc \u0648\u0631\u062a\u06cc\u0646\u062f\u0627 \u067e\u0626\u06d2: %1",
	"Using HTTP proxy to get URL: %1": "\u06cc\u0648 \u0622\u0631 \u0627\u06cc\u0644 \u0622\u0646\u0768 \u06a9\u06cc\u062a\u06d2 HTTP \u067e\u0631\u0648\u06a9\u0633\u06cc \u0648\u0631\u062a\u06cc\u0646\u062f\u0627 \u067e\u0626\u06d2: %1",
	"\u4f7f\u7528\u65b0 agent\u3002": "\u0646\u0648\u0627\u06ba \u0627\u06cc\u062c\u0646\u0679 \u0648\u0631\u062a\u06cc\u0646\u062f\u0627 \u067e\u0626\u06d2\u06d4",
	"\u4f7f\u7528\u81ea\u5b9a\u7fa9 agent\u3002": "\u062d\u0633\u0628 \u0636\u0631\u0648\u0631\u062a \u0627\u06cc\u062c\u0646\u0679 \u0648\u0631\u062a\u06cc\u0646\u062f\u0627 \u067e\u0626\u06d2\u06d4",
	"\u81ea\u5b9a\u7fa9 agent \u8207 URL \u4e4b\u5354\u5b9a\u4e0d\u540c\uff0c\u5c07\u5617\u8a66\u63a1\u7528\u7b26\u5408\u7684\u5354\u5b9a\uff1a%1": "\u062d\u0633\u0628 \u0636\u0631\u0648\u0631\u062a \u0627\u06cc\u062c\u0646\u0679 \u06cc\u0648 \u0622\u0631 \u0627\u06cc\u0644 \u062a\u0648\u06ba \u0645\u062e\u062a\u0644\u0641 \u0627\u06d2 \u062a\u06d2 \u0645\u0648\u0627\u0641\u0642 \u0645\u0639\u0627\u06c1\u062f\u06d2 \u06a9\u0648\u06ba \u0627\u067e\u0646\u0627\u0648\u0768 \u062f\u06cc \u06a9\u0648\u0634\u0634 \u06a9\u0631\u06cc\u0633\u06cc: %1",
	"\u63a1\u7528\u6cdb\u7528\u7684 agent\u3002": "\u0639\u0627\u0645 \u0627\u06cc\u062c\u0646\u0679 \u0648\u0631\u062a\u06cc\u0646\u062f\u0627 \u067e\u0626\u06d2\u06d4",
	"\u91cd\u65b0\u8a2d\u5b9a cookie \u6210\uff1a%1": "\u06a9\u0648\u06a9\u06cc \u06a9\u0648\u06ba \u0627\u06cc\u06c1\u0691\u06d2 \u062a\u06d2 \u0631\u06cc \u0633\u06cc\u0679 \u06a9\u0631\u0648: %1",
	"Retry %1/%2: %3": "\u0648\u0644\u062f\u0627 \u06a9\u0648\u0634\u0634 \u06a9\u0631\u0648 %1/%2: %3",
	"URL not found: [%1]": "\u06cc\u0648 \u0622\u0631 \u0627\u06cc\u0644 \u0646\u0626\u06cc\u06ba \u0644\u0628\u06be\u06cc\u0627: [%1]",
