	"\u6a94\u6848\u540d\u7a31\uff1a%1": "\u0641\u0627\u0626\u0644 \u0646\u0627\u06ba: %1",
	"Got URL [%1], but there is no listener!": "\u06cc\u0648 \u0622\u0631 \u0627\u06cc\u0644 [%1] \u0645\u0644\u06cc\u0627\u060c \u067e\u0631 \u06a9\u0648\u0626\u06cc \u0633\u0646\u0768 \u0622\u0644\u0627 \u06a9\u0627\u0626\u0646\u06cc!",
	"\u7b49\u5f85\u63a5\u6536\u5f9e\u7db2\u5740 [%1] \u50b3\u8f38\u56de\u7684\u8cc7\u6599\u2026\u2026": "\u06cc\u0648 \u0622\u0631 \u0627\u06cc\u0644 [%1] \u062a\u0648\u06ba \u0645\u0648\u0691\u0627 \u06b3\u06cc\u0627 \u0688\u06cc\u0679\u0627 \u0645\u0648\u0635\u0648\u0644 \u06a9\u0631\u0768 \u062f\u0627 \u0627\u0646\u062a\u0638\u0627\u0631...",
	"Unknown HTTP compression method: [%1]": "\u0646\u0627\u0648\u0627\u0642\u0641 HTTP \u062f\u0628\u0627\u0624 \u062f\u0627 \u0637\u0631\u06cc\u0642\u06c1: [%1]",
	"You need to bypass the DDoS protection by Cloudflare!": "\u062a\u0633\u0627\u06ba \u06a9\u0648\u06ba \u06a9\u0644\u0627\u0624\u0688 \u0641\u0644\u06cc\u0626\u0631 \u062f\u06cc \u0688\u06cc \u0688\u0627\u0633 \u062d\u0641\u0627\u0638\u062a \u06a9\u0648\u06ba \u0686\u06be\u0648\u0691 \u06a9\u06d2 \u0627\u06b3\u0648\u06ba \u0648\u0646\u0684\u0768 \u062f\u06cc \u0644\u0648\u0691 \u0627\u06d2!",
	"Write %2 {{PLURAL:%2|byte|bytes}} to file [%1]: %3": "\u0641\u0627\u0626\u0644 [%1] \u0648\u0686 %2 {{PLURAL:%2|byte|bytes}} \u0644\u06a9\u06be\u0648: %3",
	"Failed to write %2 {{PLURAL:%2|byte|bytes}} to [%1]: %3": "\u0641\u0627\u0626\u0644 [%1] \u0648\u0686 %2 {{PLURAL:%2|byte|bytes}} \u0644\u06a9\u06be\u0768 \u0648\u0686 \u0646\u0627\u06a9\u0627\u0645\u06cc: %3",
