	"\u91cd\u65b0\u7372\u53d6\u6a94\u6848\u5f8c\u767c\u73fe\u539f\u6a94\u6848\u5df2\u5b58\u5728\uff0c\u8df3\u904e\u4e0d\u8986\u5beb\uff1a[%1]": "\u0648\u06cc\u0628 \u062a\u0648\u06ba \u0641\u0627\u0626\u0644 \u0622\u0646\u0768 \u062f\u06d2 \u0628\u0639\u062f \u0644\u0628\u06be\u06cc\u0627 \u06b3\u06cc\u0627 \u062c\u0648 \u0641\u0627\u0626\u0644 \u0645\u0648\u062c\u0648\u062f \u0627\u06d2: [%1]\u06d4 \u0627\u06cc\u0646\u062f\u06cc \u062a\u06be\u0627\u06ba \u067b\u0626\u06cc \u0646\u0626\u06cc\u06ba \u0644\u06a9\u06be\u0768\u06cc\u06d4",
	"Write data to cache file [%1].": "\u06a9\u06cc\u0686 \u0641\u0627\u0626\u0644 [%1] \u0648\u0686 \u0688\u06cc\u0679\u0627 \u0644\u06a9\u06be\u0648\u06d4",
