	"download_options.data_directory": "\u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u062f\u06cc \u0645\u0631\u06a9\u0632\u06cc \u0688\u0627\u0626\u0631\u06cc\u06a9\u0679\u0631\u06cc \u067e\u06c1\u0644\u0648\u06ba \u062a\u0648\u06ba \u0637\u06d2 \u06a9\u0631\u0648\u06d4 \u06c1\u0631 \u0648\u06cc\u0628 \u0633\u0627\u0626\u0679 \u062f\u06cc\u0627\u06ba \u0630\u06cc\u0644\u06cc \u0688\u0627\u0626\u0631\u06cc\u06a9\u0679\u0631\u06cc\u0627\u06ba (\u06cc\u0639\u0646\u06cc main_directory) \u0627\u06cc\u0646\u062f\u0627 \u0688\u0627\u0626\u0631\u06cc\u06a9\u0679\u0631\u06cc \u0648\u0686 \u0628\u0768\u0633\u0646\u060c \u062a\u06d2 \u06c1\u0631 \u0648\u06cc\u0628 \u0633\u0627\u0626\u0679 \u062a\u0648\u06ba \u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u062a\u06be\u06cc\u0627\u06ba \u0641\u0627\u0626\u0644\u0627\u06ba \u0627\u06cc\u0646\u062f\u0627 \u0630\u06cc\u0644\u06cc \u0688\u0627\u0626\u0631\u06cc\u06a9\u0679\u0631\u06cc \u0648\u0686 \u0631\u06a9\u06be\u06cc\u0627\u06ba \u0648\u06cc\u0633\u0646\u06d4 \u062c\u06d2 \u0688\u0644\u06cc\u0679 \u06a9\u0631 \u0759\u062a\u06cc \u06b3\u0626\u06cc \u062a\u0627\u06ba \u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u0688\u0627\u0626\u0631\u06cc\u06a9\u0679\u0631\u06cc \u0628\u06cc\u0627 \u0628\u0768\u0627\u0626\u06cc \u0648\u06cc\u0633\u06cc\u06d4",
