	"download_options.images_archive_extension": "\u062a\u0635\u0648\u06cc\u0631\u06cc\u06ba \u0622\u0631\u06a9\u0627\u0626\u06cc\u0648 \u062f\u06cc\u0627\u06ba \u0641\u0627\u0626\u0644\u0627\u06ba \u06a9\u06cc\u062a\u06d2 \u0641\u0627\u0626\u0644 \u0627\u06cc\u06a9\u0633\u0679\u06cc\u0646\u0634\u0646\u06d4 \u0645\u062b\u0627\u0644 \u0637\u0648\u0631\u060c \"cbz\"\u06d4 \u067e\u06c1\u0644\u0648\u06ba \u062a\u0648\u06ba: \"zip\"\u06d4",
