	"download_options.start_list_serial": "\u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u0634\u0631\u0648\u0639 \u06a9\u0631\u0768 \u0622\u0644\u06d2 \u06a9\u0645 \u062f\u0627 \u0633\u06cc\u0631\u06cc\u0644 \u0646\u0645\u0628\u0631 \u0637\u06d2 \u06a9\u0631\u0648\u06d4 \u0627\u06cc\u0646\u062f\u0627 \u0633\u06cc\u0631\u06cc\u0644 \u0646\u0645\u0628\u0631 \u062a\u0648\u06ba \u067e\u06c1\u0644\u0648\u06ba \u0622\u0644\u0627 \u06a9\u0645 \u0686\u06be\u0648\u0691 \u0759\u062a\u0627 \u0648\u06cc\u0633\u06cc\u06d4 \u0639\u0627\u0645 \u0637\u0648\u0631 \u062a\u06d2 \u0635\u0631\u0641 \u06a9\u0645\u0627\u0646\u0688 \u0644\u0627\u0626\u0646 \u0633\u06cc\u0679\u0646\u06af\u0632 \u0648\u0686 \u0648\u0631\u062a\u06cc\u0627 \u0648\u06cc\u0646\u062f\u0627 \u0627\u06d2\u06d4 \u067e\u06c1\u0644\u0648\u06ba \u062a\u0648\u06ba:1",
