	"\u91cd\u8a2d\u4e0b\u8f09\u9078\u9805\u8207\u6700\u611b\u4f5c\u54c1\u6e05\u55ae": "\u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u0622\u067e\u0634\u0646\u0632 \u062a\u06d2 \u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u06cc \u0641\u06c1\u0631\u0633\u062a \u0631\u06cc \u0633\u06cc\u0679 \u06a9\u0631\u0648",
