	"\u8acb\u5728\u6bcf\u4e00\u884c\u9375\u5165\u4e00\u500b\u4f5c\u54c1\u540d\u7a31\u6216\ud83c\udd94\uff1a": "\u06c1\u0631 \u0633\u0637\u0631 \u062a\u06d2 \u06c1\u06a9 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u0627 \u0633\u0631\u0646\u0627\u0648\u0627\u06ba \u06cc\u0627 \ud83c\udd94 \u0644\u06a9\u06be\u0648",
	"\u5132\u5b58\u6700\u611b\u4f5c\u54c1\u6e05\u55ae": "\u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u06cc \u0641\u06c1\u0631\u0633\u062a \u0645\u062d\u0641\u0648\u0638 \u06a9\u0631\u0648",
	"\u653e\u68c4\u7de8\u8f2f\u6700\u611b\u4f5c\u54c1\u6e05\u55ae": "\u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u06cc \u0641\u06c1\u0631\u0633\u062a \u062f\u06cc \u062a\u0631\u0645\u06cc\u0645 \u0686\u06be\u0648\u0691\u0648",
	"\u5132\u5b58\u6700\u611b\u4f5c\u54c1\u6e05\u55ae\u7684\u6a94\u6848\u4e0d\u5b58\u5728\u6216\u8005\u6c92\u6709\u5167\u5bb9\u3002\u63a1\u7528\u820a\u6709\u7684\u6700\u611b\u4f5c\u54c1\u5217\u8868\u3002": "\u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u06cc \u0641\u06c1\u0631\u0633\u062a \u0646\u0626\u06cc\u06ba \u0645\u0644\u06cc \u06cc\u0627 \u062e\u0627\u0644\u06cc \u0627\u06d2\u06d4 \u067e\u0631\u0627\u0768\u06cc \u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u06cc \u0641\u06c1\u0631\u0633\u062a \u0648\u0631\u062a\u06cc\u0646\u062f\u06cc \u067e\u0626\u06cc \u0627\u06d2\u06d4",
	"\u958b\u5553\u4f5c\u54c1\u4e0b\u8f09\u76ee\u9304": "\u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u0641\u0648\u0644\u0688\u0631 \u06a9\u06be\u0648\u0644\u0648",
	"\u4f5c\u54c1\u5df2\u5b8c\u7d50\u3002": "\u0633\u06cc\u0631\u06cc\u0632 \u0645\u06a9\u0645\u0644 \u062a\u06be\u06cc \u06b3\u0626\u06cc \u0627\u06d2\u06d4",
	"\u5f9e\u6700\u611b\u540d\u55ae\u4e2d\u6ce8\u89e3\u6389\u672c\u4f5c\u54c1\u3002": "\u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u06cc \u0641\u06c1\u0631\u0633\u062a \u062a\u0648\u06ba \u0633\u06cc\u0631\u06cc\u0632 \u06a9\u0688\u06be\u0648",
	"%1 \u5df2\u5b8c\u7d50\u7684\u4f5c\u54c1\u540d\u7a31\u6216\ud83c\udd94\uff1a%2": "%1 \u0645\u06a9\u0645\u0644 \u062a\u06be\u06cc \u06b3\u0626\u06cc \u0633\u06cc\u0631\u06cc\u0632 \u06cc\u0627 \ud83c\udd94: %2",
	"\u6aa2\u67e5\u6240\u6709\u6700\u611b\u4f5c\u54c1\u4e4b\u66f4\u65b0\uff0c\u4e26\u4e0b\u8f09\u66f4\u65b0\u4f5c\u54c1\u3002": "\u0633\u0627\u0631\u06cc\u0627\u06ba \u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u06cc\u0627\u06ba \u0627\u067e \u0688\u06cc\u0679\u0633 \u0648\u06cc\u06a9\u06be\u0648 \u062a\u06d2 \u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u06a9\u0631\u0648\u06d4",
	"\ud83c\ude33 \u5c1a\u7121\u6700\u611b\u4f5c\u54c1\u3002": "\u06a9\u0648\u0626\u06cc \u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u06cc \u0641\u06c1\u0631\u0633\u062a \u0646\u0626\u06cc\u06ba \u0627\u06d2",
	"\ud83c\ude33 \u5c1a\u672a\u8a2d\u5b9a\u6700\u611b\u4f5c\u54c1\u3002": "\u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u06cc \u0641\u06c1\u0631\u0633\u062a \u062e\u0627\u0644\u06cc \u0627\u06d2",
	"\u7de8\u8f2f\u6700\u611b\u4f5c\u54c1\u6e05\u55ae": "\u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0633\u06cc\u0631\u06cc\u0632 \u062f\u06cc \u0641\u06c1\u0631\u0633\u062a \u0648\u0686 \u062a\u0631\u0645\u06cc\u0645 \u06a9\u0631\u0648",
	"\u522a\u9664\u6240\u6709 %1 \u500b{{PLURAL:%1|\u8a3b\u89e3}}\u3001%2 \u500b{{PLURAL:%2|\u91cd\u8907\u4f5c\u54c1\u540d\u7a31}}\u8207 %3 \u500b{{PLURAL:%3|\u7a7a\u884c}}\u3002": "\u06a9\u0688\u06be\u0648 \u0633\u0627\u0631\u06d2 {{PLURAL:%1|annotation|annotations}}, %2 {{PLURAL:%2|repetition|repetitions}}, and %3 blank {{PLURAL:%3|line|lines}}\u06d4",
	"\u5217\u8868\u6a94\u6848\u4e2d\u6709 %1 \u500b\u91cd\u8907\u4f5c\u54c1\u540d\u7a31\u6216\ud83c\udd94\u3002": "\u0641\u06c1\u0631\u0633\u062a \u0648\u0686 %1 \u062f\u06c1\u0631\u06d2 \u0633\u0631\u0646\u0627\u0648\u06d2 \u06cc\u0627 \ud83c\udd94 \u06c1\u0646\u06d4",
	"\u6ce8\u89e3\u6389\u91cd\u8907\u7684\u4f5c\u54c1\u540d\u7a31\u6216\ud83c\udd94": "\u062f\u06c1\u0631\u06d2 \u06a9\u0645\u0627\u06ba \u062f\u06d2 \u0646\u0627\u06ba \u06cc\u0627 \ud83c\udd94 \u062a\u06d2 \u062a\u0628\u0635\u0631\u06c1 \u0644\u0627\u0624",
	"\u522a\u9664\u91cd\u8907\u7684\u4f5c\u54c1\u540d\u7a31\u6216\ud83c\udd94": "\u062f\u06c1\u0631\u06d2 \u06a9\u0645\u0627\u06ba \u062f\u06d2 \u0646\u0627\u06ba \u06cc\u0627 \ud83c\udd94 \u06a9\u0688\u06be\u0648",
	"\u6ce8\u89e3\u6389%1\u500b\u5df2\u5b8c\u7d50\u7684\u4f5c\u54c1\u540d\u7a31\u6216\ud83c\udd94": "%1 \u0645\u06a9\u0645\u0644 \u06a9\u0645\u0627\u06ba \u062f\u06d2 \u0646\u0627\u06ba \u06cc\u0627 \ud83c\udd94 \u062a\u0628\u0635\u0631\u06d2 \u0648\u0686 \u067e\u0627\u0626\u06d2 \u06b3\u0626\u06d2",
	"\u8b80\u53d6\u672c\u7db2\u7ad9\u5404\u4f5c\u54c1\u4e4b\u8cc7\u8a0a\u6a94\u6848\uff0c\u4ee5\u5224\u5225\u4f5c\u54c1\u662f\u5426\u5df2\u4e0b\u8f09\u904e\u3001\u662f\u5426\u5b8c\u7d50\u3002": "\u0627\u06cc\u0646\u062f\u0627 \u0648\u06cc\u0628 \u0633\u0627\u0626\u0679 \u062f\u06cc \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0641\u0627\u0626\u0644 \u067e\u0691\u06be\u06cc \u0648\u06cc\u0646\u062f\u06cc \u067e\u0626\u06cc \u0627\u06d2 \u062a\u0627\u06ba \u062c\u0648 \u0627\u06cc\u0646\u062f\u0627 \u0637\u06d2 \u06a9\u06cc\u062a\u0627 \u0648\u0646\u0684\u06d2 \u062c\u0648 \u06a9\u0645 \u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u062a\u06d2 \u0645\u06a9\u0645\u0644 \u062a\u06be\u06cc \u06b3\u06cc\u0627 \u0627\u06d2 \u06cc\u0627 \u0646\u0626\u06cc\u06ba\u06d4 ",
	"\u9078\u64c7\u7db2\u7ad9\u6642\uff0c\u9019\u53ef\u80fd\u9020\u6210\u5e7e\u5341\u79d2\u9418\u7121\u56de\u61c9\u3002": "\u062c\u0688\u0627\u06ba \u0648\u06cc\u0628 \u0633\u0627\u0626\u0679 \u0686\u064f\u0768\u06cc \u0648\u06cc\u0646\u062f\u06cc \u0627\u06d2\u060c \u062a\u0627\u06ba \u06a9\u062c\u06be \u0633\u06cc\u06a9\u0646\u0688 \u06a9\u06cc\u062a\u06d2 \u062c\u0648\u0627\u0628 \u0646\u0627\u06ba \u0645\u0644 \u0633\u06af\u062f\u0627 \u0627\u06d2\u06d4",
	"\u8b80\u53d6\u6240\u6709\u7db2\u7ad9\u4e4b\u4f5c\u54c1\u8cc7\u8a0a\u6a94\u6848": "\u0633\u0627\u0631\u06cc\u0627\u06ba \u0648\u06cc\u0628 \u0633\u0627\u0626\u0679\u0627\u06ba \u062a\u0648\u06ba \u06a9\u0645 \u062f\u06cc \u0633\u0645\u06af\u0631\u06cc \u067e\u0691\u06be\u06cc \u0648\u06cc\u0646\u062f\u06cc \u067e\u0626\u06cc \u0627\u06d2",
