	"\u8cc7\u8a0a\u4f86\u81ea\u7ae0\u7bc0\u6e05\u55ae": "\u0628\u0627\u0628\u0627\u06ba \u062f\u06cc \u0641\u06c1\u0631\u0633\u062a \u062a\u0648\u06ba \u0633\u0645\u06af\u0631\u06cc",
