	"\u4e0b\u8f09\u6240\u6709\u6700\u611b\u6e05\u55ae\u4e2d\u7684\u672c\u4f5c\u54c1": "\u067e\u0633\u0646\u062f\u06cc\u062f\u06c1 \u0641\u06c1\u0631\u0633\u062a\u0627\u06ba \u062a\u0648\u06ba \u0633\u0627\u0631\u06d2 \u06a9\u0645 \u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u06a9\u0631\u0648\u06d4",
